        if (r, c) == goal:
            return path + [(r, c)]

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == '.' and (nr, nc) not in path:
                    result = dfs(nr, nc, path + [(r, c)])
                    if result:
